// build_schema_bundle.js
//
// Rebuilds supabase_deploy_all.sql from the files in sql/.
//
// -------------------------------------------------------------------------
// WHY THIS EXISTS
// -------------------------------------------------------------------------
// The bundle used to be assembled by hand, and by October 2026 it had drifted
// four migrations behind: v13 (import batch hash), v14 (RLS), v15 (unique
// constraint normalisation) and v16 (system admin) were all missing. Anyone
// standing up a fresh database from it got a schema the code does not match —
// the investor import, for one, fails on ON CONFLICT without v12/v15's unique
// indexes, and nothing says why.
//
// A hand-maintained list is exactly the kind of thing that goes stale without
// anyone noticing, so MIGRATIONS below is checked against the contents of
// sql/ on every run: add a schema_update_*.sql and forget to list it here and
// this script refuses to write anything.
//
// Usage:
//   node scripts/build_schema_bundle.js --check   # verify the bundle is current
//   node scripts/build_schema_bundle.js           # rewrite it

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SQL_DIR = path.join(ROOT, 'sql');
const OUT_FILE = path.join(ROOT, 'supabase_deploy_all.sql');

const CHECK_ONLY = process.argv.includes('--check');

// Order matters and is not alphabetical: maidan_schema creates facilities,
// which users (in auth_schema) has a foreign key to. The numbered migrations
// then apply in sequence, each assuming the ones before it.
const BASE = ['maidan_schema.sql', 'auth_schema.sql'];

// Files in sql/ that are deliberately NOT part of the bundle.
//   sample_insert_data.sql  — demo rows, never wanted on a real database
//   seed_reference.sql      — lookup data, generated by build_reference_seed.js
//                             and applied as a separate step after the schema
const EXCLUDED = new Set(['sample_insert_data.sql', 'seed_reference.sql']);

function orderedMigrations() {
  return fs
    .readdirSync(SQL_DIR)
    .filter((f) => /^schema_update_v\d+.*\.sql$/.test(f))
    .sort((a, b) => Number(a.match(/^schema_update_v(\d+)/)[1]) - Number(b.match(/^schema_update_v(\d+)/)[1]));
}

// Every .sql in the directory must be accounted for — bundled, base, or
// explicitly excluded. This is the check that would have caught the drift.
function assertNothingUnaccountedFor(files) {
  const known = new Set([...BASE, ...files, ...EXCLUDED]);
  const stray = fs.readdirSync(SQL_DIR).filter((f) => f.endsWith('.sql') && !known.has(f));
  if (stray.length) {
    console.error('These files in sql/ are in neither the bundle nor the exclusion list:');
    for (const f of stray) console.error(`  sql/${f}`);
    console.error('\nAdd them to the migration naming scheme, or to EXCLUDED with a reason.');
    process.exit(1);
  }
}

// Migration numbers must be a gap-free run from 2. A gap means a file was
// renamed or lost, and the bundle would silently skip that step.
function assertNoGaps(files) {
  const nums = files.map((f) => Number(f.match(/^schema_update_v(\d+)/)[1]));
  const missing = [];
  for (let n = 2; n <= Math.max(...nums); n += 1) if (!nums.includes(n)) missing.push(n);
  if (missing.length) {
    console.error(`Missing migration(s): v${missing.join(', v')}. Bundle not written.`);
    process.exit(1);
  }
}

function build(files) {
  const parts = [];
  parts.push(`-- Maidan — full schema, generated ${new Date().toISOString().replace(/\.\d+Z$/, 'Z')}`);
  parts.push('-- by scripts/build_schema_bundle.js. Do not edit by hand: edit the');
  parts.push('-- files in sql/ and re-run that script, or your change is lost on the');
  parts.push('-- next rebuild.');
  parts.push('--');
  parts.push('-- Paste into the Supabase SQL Editor and Run, or apply with');
  parts.push('-- scripts/run_schema_on_prod.js.');
  parts.push('--');
  parts.push('-- Wrapped in a transaction: Postgres DDL is transactional, so if any');
  parts.push('-- statement fails the whole thing rolls back and you are left with an');
  parts.push('-- empty database rather than a half-built schema.');
  parts.push('');
  parts.push('BEGIN;');
  parts.push('');

  for (const f of [...BASE, ...files]) {
    parts.push('-- ============================================================');
    parts.push(`-- sql/${f}`);
    parts.push('-- ============================================================');
    // Each source file's own BEGIN/COMMIT would close the outer transaction
    // partway through, so they are stripped; the bundle supplies one.
    // CR is stripped so the bundle is uniformly LF. The sql/ sources are
    // CRLF on a Windows checkout and the header below is built with '\n',
    // and mixing the two made the output differ from machine to machine.
    const body = fs
      .readFileSync(path.join(SQL_DIR, f), 'utf8')
      .replace(/\r/g, '')
      .replace(/^[ \t]*(BEGIN|COMMIT)[ \t]*;[ \t]*$/gim, '')
      .trim();
    parts.push(body);
    parts.push('');
  }

  parts.push('COMMIT;');
  parts.push('');
  return parts.join('\n');
}

const files = orderedMigrations();
assertNothingUnaccountedFor(files);
assertNoGaps(files);

const bundled = [...BASE, ...files];
const next = build(files);

// The generated-on timestamp changes every run, so comparing whole files
// would always report a difference. Compare everything below the header.
//
// CR is stripped on both sides first: git rewrites line endings on checkout,
// so without this --check reports STALE on a fresh clone on Windows even
// though the content is identical — and a check that cries wolf every time
// is a check people learn to ignore.
const bodyOf = (s) => {
  const lf = s.replace(/\r/g, '');
  return lf.slice(lf.indexOf('BEGIN;'));
};

if (CHECK_ONLY) {
  const current = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, 'utf8') : '';
  if (bodyOf(current) === bodyOf(next)) {
    console.log(`OK: supabase_deploy_all.sql is current (${bundled.length} files).`);
    process.exit(0);
  }
  console.error('STALE: supabase_deploy_all.sql does not match sql/. Run:');
  console.error('  node scripts/build_schema_bundle.js');
  process.exit(1);
}

fs.writeFileSync(OUT_FILE, next);
console.log(`Wrote supabase_deploy_all.sql from ${bundled.length} files:`);
for (const f of bundled) console.log(`  sql/${f}`);
